'use strict';
const novaKinds={in:'Entrada','break-start':'Saída para almoço','break-end':'Volta do almoço',out:'Saída'};
const novaWeekdays=[['1','Segunda-feira'],['2','Terça-feira'],['3','Quarta-feira'],['4','Quinta-feira'],['5','Sexta-feira'],['6','Sábado'],['0','Domingo']];
const novaHours=minutes=>minutes===null||minutes===undefined?'—':`${minutes<0?'−':''}${Math.floor(Math.abs(minutes)/60)}h ${String(Math.abs(minutes)%60).padStart(2,'0')}min`;
function novaScheduleText(planned){return !planned?.configured?'Horário ainda não cadastrado':!planned.segments.length?'Sem expediente previsto':planned.segments.map(s=>s.start+' às '+s.end).join(' · ')}
async function loadNovaPoint(render=true){novaAuth.point=await requestShared('/api/time/me');novaAuth.serverOffset=Date.parse(novaAuth.point.serverTime)-Date.now();if(page==='point'&&novaAuth.stage==='ready'&&(!document.getElementById('modal').open||render))shell()}
function novaPointView(){const value=novaAuth.point;if(!value)return pageHead('Meu ponto','Carregando sua jornada…');const d=value.summary,mode=novaCurrentUser().punchMode,buttons=mode==='two'?['in','out']:['in','break-start','break-end','out'];const late=d.firstEntryDifferenceMinutes;const suggested=d.status==='break'?'break-end':d.status==='working'?(mode==='two'||d.effective.at(-1)?.kind==='break-end'?'out':'break-start'):'in';return `${pageHead('Meu ponto','Seu horário e seus registros de jornada.')}<section class="panel nova-point-panel"><div class="section-head"><div><span class="nova-eyebrow">Agora na empresa</span><div id="nova-clock" class="nova-clock">${novaClock()}</div><p>${new Date(value.serverTime).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p></div>${badge(d.status==='working'?'green':d.status==='break'?'yellow':'pending',{working:'Jornada aberta',break:'Em intervalo',outside:'Sem jornada aberta'}[d.status])}</div><div class="nova-planned"><strong>Horário previsto</strong><p>${esc(novaScheduleText(d.planned))}</p>${d.planned.note?`<p class="help">${esc(d.planned.note)}</p>`:''}</div>${value.canPunch?`<p class="help">${value.companyNetwork?'Conectado à rede da empresa.':'Exceção de rede autorizada para sua conta.'} Selecione a marcação que está realizando agora.</p>`:'<p class="rule-note">Conecte-se ao Wi-Fi da empresa para registrar o ponto. Se você trabalha fora, peça à administração a autorização da exceção.</p>'}<div class="nova-punch-buttons">${buttons.map(k=>`<button type="button" data-nova-action="punch" data-kind="${k}" class="${k===suggested?'primary':''}" ${novaAuth.punching||!value.canPunch?'disabled':''}>${esc(novaKinds[k])}</button>`).join('')}</div><p class="help">A hora é registrada pelo servidor quando você confirma a marcação. Sem conexão, aguarde a confirmação antes de considerar o ponto registrado.</p></section><div class="operational-overview"><section class="panel"><h2>Jornada de ${fmt(d.date)}</h2><p class="capacity-value">${novaHours(d.workedMinutes)}</p><p class="help">Tempo de períodos já encerrados${d.status!=='outside'?'. Há uma marcação de fechamento pendente.':'.'}</p>${d.planned.minutes!==null?`<p>Previsto: ${novaHours(d.planned.minutes)}</p>`:''}${late!==null?`<p class="help">Primeira entrada: ${late===0?'no horário previsto':Math.abs(late)+' min '+(late>0?'após':'antes do')+' horário previsto'}.</p>`:''}${d.anomalies.map(s=>`<p class="rule-note">${esc(s)}</p>`).join('')}</section><section class="panel"><h2>Marcações originais</h2>${d.original.length?d.original.map(p=>`<div class="nova-punch-row"><div><strong>${esc(novaKinds[p.kind])}</strong><small>${novaClock(p.at)} · Registro ${p.sequence}</small></div>${novaButton('receipt','Ver registro',`data-receipt="${esc(p.id)}"`)}</div>`).join(''):'<p class="help">Nenhuma marcação nesta jornada.</p>'}${d.adjustments.length?`<p class="help">Há ${d.adjustments.length} ajuste(s) identificado(s) na apuração. Os registros originais foram preservados.</p>`:''}</section></div><section class="panel"><div class="section-head"><div><h2>Meu histórico</h2><p class="help">Consulte as marcações e os ajustes do mês.</p></div><div class="actions"><label>Mês<input type="month" id="nova-own-month" value="${esc(novaAuth.report?.month||novaDate().slice(0,7))}"></label>${novaButton('own-report','Consultar')}</div></div>${novaAuth.report?novaReportView(novaAuth.report,false):''}</section><p class="help">Controle interno de jornada. Diferenças de horário são indicativas; não geram descontos ou pagamentos automáticos.</p>`}
async function novaPunch(kind){if(novaAuth.punching)return;const requestId=novaAuth.pendingPunch?.kind===kind?novaAuth.pendingPunch.requestId:uid();novaAuth.pendingPunch={kind,requestId};novaAuth.punching=true;shell();try{const result=await requestShared('/api/time/punch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,requestId})});novaAuth.pendingPunch=null;await loadNovaPoint(false);novaReceiptDialog(result.entry);toast('Ponto registrado às '+novaClock(result.entry.at)+'.')}catch(e){toast('Ponto sem confirmação: '+e.message)}finally{novaAuth.punching=false;if(page==='point')shell()}}
function novaReceiptDialog(receipt){profileDialog('Ponto registrado',receipt.name||novaCurrentUser().name,`<dl class="facts"><div><dt>Marcação</dt><dd>${esc(novaKinds[receipt.kind])}</dd></div><div><dt>Data</dt><dd>${fmt(receipt.at)}</dd></div><div><dt>Hora do servidor</dt><dd>${novaClock(receipt.at)}</dd></div><div><dt>Registro</dt><dd>${receipt.sequence}</dd></div></dl><p class="help">Nova Aliança · Registro interno de jornada. Fuso: São Paulo.</p>`,novaButton('download-receipt','Baixar registro',`data-receipt="${esc(receipt.id)}"`,true)+novaButton('close-nova','Fechar'))}
function novaDownload(value,name,type='application/json'){const content=typeof value==='string'?value:JSON.stringify(value,null,2),url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function novaReportView(report,admin){return `<div class="nova-report-summary"><p><strong>${novaHours(report.totalWorkedMinutes)}</strong> de períodos encerrados</p><p>${report.completeDays} dia(s) com jornada fechada · ${report.reviewDays} dia(s) para conferir</p>${novaButton(admin?'admin-csv':'own-csv','Exportar CSV',admin?`data-employee="${esc(report.employee.id)}"`:'')}</div><div class="nova-table-scroll"><table class="nova-report-table"><thead><tr><th>Dia</th><th>Previsto</th><th>Marcações originais</th><th>Apurado</th><th>Conferência</th>${admin?'<th>Ações</th>':''}</tr></thead><tbody>${report.days.map(d=>`<tr><td>${fmt(d.date)}</td><td>${esc(novaScheduleText(d.planned))}</td><td>${d.original.map(p=>`<div>${esc(novaKinds[p.kind])} · ${novaClock(p.at)}${admin?` ${novaButton('ignore-punch','Desconsiderar',`data-employee="${esc(report.employee.id)}" data-punch="${esc(p.id)}" data-day="${d.date}"`)}`:''}</div>`).join('')||'—'}${d.adjustments.length?`<details><summary>${d.adjustments.length} ajuste(s)</summary>${d.adjustments.map(a=>`<p class="help">${a.action==='include'?'Incluído na apuração: '+esc(novaKinds[a.kind])+' às '+novaClock(a.at):'Registro desconsiderado na apuração'} · ${esc(a.reason)} · ${esc(a.actor||'Administrador')}</p>`).join('')}</details>`:''}</td><td>${d.effective.length?novaHours(d.workedMinutes):'—'}</td><td>${d.anomalies.length?esc(d.anomalies.join(' ')):d.effective.length?(d.complete?'Jornada fechada':'Jornada em aberto'):'Sem marcações'}${d.balanceMinutes!==null?'<p class="help">Diferença indicativa: '+novaHours(d.balanceMinutes)+'</p>':''}</td>${admin?`<td>${novaButton('add-adjustment','Registrar ajuste',`data-employee="${esc(report.employee.id)}" data-day="${d.date}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function novaAdminReportView(){const report=novaAuth.adminReport;if(!report)return '';return `<section class="panel" id="nova-admin-report"><div class="section-head"><div><h2>Jornada · ${esc(report.employee.name)}</h2><p class="help">Marcações originais e ajustes são apresentados separadamente.</p></div><div class="actions"><label>Mês<input type="month" id="nova-admin-month" value="${report.month}"></label>${novaButton('reload-admin-report','Consultar',`data-employee="${esc(report.employee.id)}"`)}</div></div>${novaReportView(report,true)}</section>`}
async function novaLoadAdminReport(id,month){novaAuth.adminReport=await requestShared('/api/people/'+id+'/report?month='+(month||novaDate().slice(0,7)));if(page!=='employees')page='employees';shell();document.getElementById('nova-admin-report')?.scrollIntoView({behavior:'smooth',block:'start'})}
function novaSegmentRow(day,start='',end=''){return `<div class="nova-schedule-period" data-schedule-day="${day}"><label>Entrada<input type="time" name="start-${day}" value="${esc(start)}" required></label><label>Saída<input type="time" name="end-${day}" value="${esc(end)}" required></label>${novaButton('remove-period','Remover período')}</div>`}
function novaDayBlock(key,label,segments=[]){return `<fieldset class="nova-schedule-day"><legend>${esc(label)}</legend><div class="nova-day-periods" data-periods-for="${key}">${segments.map(s=>novaSegmentRow(key,s.start,s.end)).join('')}</div>${novaButton('add-period','Adicionar período',`data-schedule-day="${key}"`)}<p class="help">Sem períodos: sem expediente previsto.</p></fieldset>`}
async function novaEditSchedule(id){closeModal();const result=await requestShared('/api/people/'+id+'/schedules'),latest=result.schedules.find(s=>s.scope==='weekly'&&s.effectiveFrom<=novaDate())||result.schedules.find(s=>s.scope==='weekly');const week=latest?.week||{};modal('Horário fixo da semana',result.user.name+' · Defina os períodos de trabalho de cada dia.',field('effectiveFrom','Válido a partir de','date',novaDate(),'required',true)+`<p class="help full">Para almoço, cadastre dois períodos, por exemplo 08:00–12:00 e 13:00–17:00. Para jornadas partidas, você pode adicionar mais períodos. Horários não bloqueiam marcações.</p><div class="full">${novaButton('copy-weekdays','Copiar segunda-feira para os dias úteis')}</div><div class="nova-week-editor full">${novaWeekdays.map(([key,label])=>novaDayBlock(key,label,week[key]||[])).join('')}</div>`+opsArea('note','Observação (opcional)',latest?.note||'',false,500)+`<div class="full">${novaButton('date-schedule','Definir uma exceção por data',`data-employee="${esc(id)}"`)}</div>`,async(f,form)=>{const week={};for(let d=0;d<7;d++)week[d]=novaReadSegments(form,String(d));await requestShared('/api/people/'+id+'/schedules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope:'weekly',effectiveFrom:f.get('effectiveFrom'),week,note:f.get('note')})});closeModal();toast('Horário salvo. Versões anteriores preservadas.');if(novaCurrentUser().id===id&&page==='point')await loadNovaPoint()},'Salvar horário')}
function novaReadSegments(form,day){return [...form.querySelectorAll(`.nova-schedule-period[data-schedule-day="${day}"]`)].map(row=>({start:row.querySelector(`[name="start-${day}"]`).value,end:row.querySelector(`[name="end-${day}"]`).value}))}
function novaDateSchedule(id){modal('Exceção de horário por data','A exceção vale somente para o dia escolhido.',field('effectiveFrom','Data da jornada','date',novaDate(),'required',true)+`<div class="full">${novaDayBlock('exception','Períodos deste dia',[])}</div>`+opsArea('note','Motivo da exceção','',true,500)+'<p class="help full">Para folga, deixe o dia sem períodos e informe o motivo. O horário fixo da semana continua preservado.</p>',async(f,form)=>{await requestShared('/api/people/'+id+'/schedules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope:'date',effectiveFrom:f.get('effectiveFrom'),segments:novaReadSegments(form,'exception'),note:f.get('note')})});closeModal();toast('Exceção de horário salva.')},'Salvar exceção')}
function novaAddAdjustment(employeeId,date){modal('Registrar ajuste de jornada','O ajuste fica identificado; as marcações originais não são alteradas.',field('workDate','Data da jornada','date',date,'required')+opsSelect('kind','Marcação a incluir',Object.entries(novaKinds),'in')+field('localTime','Data e hora informadas','datetime-local',date+'T08:00','required',true)+opsArea('reason','Motivo do ajuste','',true,1000),async f=>{await requestShared('/api/people/'+employeeId+'/adjustment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'include',workDate:f.get('workDate'),kind:f.get('kind'),localTime:f.get('localTime'),reason:f.get('reason')})});closeModal();await novaLoadAdminReport(employeeId,novaAuth.adminReport.month);toast('Ajuste registrado separadamente.')},'Registrar ajuste')}
function novaIgnorePunch(employeeId,punchId,date){modal('Desconsiderar na apuração','O registro original continuará visível e preservado.',opsArea('reason','Motivo','',true,1000),async f=>{await requestShared('/api/people/'+employeeId+'/adjustment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'ignore',punchId,workDate:date,reason:f.get('reason')})});closeModal();await novaLoadAdminReport(employeeId,novaAuth.adminReport.month)},'Registrar desconsideração')}
function novaTimeAction(action,b){let task;switch(action){case'punch':task=novaPunch(b.dataset.kind);break;case'receipt':task=requestShared('/api/time/receipt?id='+encodeURIComponent(b.dataset.receipt)).then(novaReceiptDialog);break;case'download-receipt':task=requestShared('/api/time/receipt?id='+encodeURIComponent(b.dataset.receipt)).then(value=>novaDownload(value,'registro-jornada-'+value.sequence+'.json'));break;case'own-report':task=requestShared('/api/time/report?month='+document.getElementById('nova-own-month').value).then(r=>{novaAuth.report=r;shell()});break;case'own-csv':task=requestShared('/api/time/report?month='+novaAuth.report.month).then(r=>novaDownload(novaCSV(r),'minha-jornada-'+r.month+'.csv','text/csv;charset=utf-8'));break;case'admin-csv':task=requestShared('/api/people/'+b.dataset.employee+'/report?month='+novaAuth.adminReport.month).then(r=>novaDownload(novaCSV(r),'jornada-'+r.month+'.csv','text/csv;charset=utf-8'));break;case'reload-admin-report':task=novaLoadAdminReport(b.dataset.employee,document.getElementById('nova-admin-month').value);break;case'add-adjustment':return novaAddAdjustment(b.dataset.employee,b.dataset.day);case'ignore-punch':return novaIgnorePunch(b.dataset.employee,b.dataset.punch,b.dataset.day);case'copy-weekdays':{const form=document.getElementById('modal-form'),segments=novaReadSegments(form,'1');if(!segments.length)return toast('Preencha primeiro os períodos de segunda-feira.');for(const d of ['2','3','4','5']){const holder=form.querySelector(`[data-periods-for="${d}"]`);holder.innerHTML=segments.map(s=>novaSegmentRow(d,s.start,s.end)).join('')}return}case'add-period':{const container=document.querySelector(`[data-periods-for="${b.dataset.scheduleDay}"]`);if(container.children.length>=6)return toast('Use até seis períodos por dia.');container.insertAdjacentHTML('beforeend',novaSegmentRow(b.dataset.scheduleDay));return}case'remove-period':return b.closest('.nova-schedule-period').remove();case'date-schedule':return novaDateSchedule(b.dataset.employee)}if(task?.catch)task.catch(e=>toast(e.message))}
function novaCSV(report){const cell=value=>{let s=String(value??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const rows=[['Funcionário','Matrícula','Data','Marcações originais','Ajustes','Minutos previstos','Minutos apurados','Saldo indicativo','Conferência'],...report.days.map(d=>[report.employee.name,report.employee.employeeCode,d.date,d.original.map(p=>novaKinds[p.kind]+' '+new Date(p.at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})).join(' | '),d.adjustments.map(a=>a.action+' '+(a.kind||a.punchId)+' '+(a.at||'')+' · '+a.reason+' · '+a.actor).join(' | '),d.planned.minutes??'',d.workedMinutes,d.balanceMinutes??'',d.anomalies.join(' / ')||(!d.effective.length?'Sem marcações':d.complete?'Jornada fechada':'Jornada em aberto')])];return '\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n')}
